import{_ as t,a as i,b as n}from"./chunks/bind_id.cROGXoYi.js";import{_ as a,o,c as s,a0 as r}from"./chunks/framework.DRjqbEpm.js";const b=JSON.parse('{"title":"3. Adaptive Engine: Training New Sites","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/adaptive-engine.md","filePath":"en/guide/adaptive-engine.md"}'),l={name:"en/guide/adaptive-engine.md"};function d(g,e,c,p,u,h){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-adaptive-engine-training-new-sites" tabindex="-1">3. Adaptive Engine: Training New Sites <a class="header-anchor" href="#_3-adaptive-engine-training-new-sites" aria-label="Permalink to &quot;3. Adaptive Engine: Training New Sites&quot;">​</a></h1><p>If you encounter a video website that V-Train cannot automatically identify, you can manually train it using the exclusive &quot;Adaptive Engine&quot;!</p><blockquote><p><img src="'+t+'" alt="Training Mode Overview"></p></blockquote><h3 id="training-steps" tabindex="-1">Training Steps: <a class="header-anchor" href="#training-steps" aria-label="Permalink to &quot;Training Steps:&quot;">​</a></h3><ol><li><strong>Start Engine</strong>: On the target website, <strong>right-click on any video thumbnail</strong>, then choose a module (Mod 1 ~ Mod 4) to save to from the V-Train panel in the bottom left.</li><li><strong>Visual Capture</strong>: <blockquote><p><img src="'+i+'" alt="Visual Capture Box"> A green or red selection box will appear on the screen.</p></blockquote><ul><li>Use the keyboard <strong><code>↑</code> (Up) / <code>↓</code> (Down)</strong> arrow keys to expand or shrink the selection range.</li><li>Please ensure the selection box <strong>exactly covers the entire thumbnail image</strong>, without selecting the text title outside.</li><li>Press <strong><code>Enter</code></strong> to confirm when adjusted.</li></ul></li><li><strong>Input Video URL</strong>: Click the thumbnail to enter the video playback page, copy the full URL from the address bar, and paste it into the V-Train panel.</li><li><strong>Bind ID</strong>: The system will analyze the URL and list possible ID segments. Please click the segment that looks most like the &quot;unique video ID&quot;. <blockquote><p><img src="'+n+'" alt="Bind ID"></p></blockquote></li><li><strong>Finish Training</strong>: Click save. Now return to the homepage, and you will find that all videos on the site have successfully been hooked with a progress bar!</li></ol>',5)])])}const v=a(l,[["render",d]]);export{b as __pageData,v as default};
